// Helper functions for state display
func stateToClass(state string) string {
	switch state {
	case "draft":
		return "is-light"
	case "validated":
		return "is-info"
	case "published":
		return "is-link"
	case "active":
		return "is-success"
	case "paused":
		return "is-warning"
	case "draining":
		return "is-warning is-light"
	case "stopped":
		return "is-dark"
	case "archived":
		return "is-grey"
	default:
		return "is-light"
	}
}

func stateToIcon(state string) string {
	switch state {
	case "draft":
		return "fas fa-pencil-alt"
	case "validated":
		return "fas fa-check-circle"
	case "published":
		return "fas fa-upload"
	case "active":
		return "fas fa-running"
	case "paused":
		return "fas fa-pause-circle"
	case "draining":
		return "fas fa-hourglass-half"
	case "stopped":
		return "fas fa-stop-circle"
	case "archived":
		return "fas fa-archive"
	default:
		return "fas fa-question-circle"
	}
}

func stateToLabel(state string) string {
	switch state {
	case "draft":
		return "Draft"
	case "validated":
		return "Validated"
	case "published":
		return "Published"
	case "active":
		return "Active"
	case "paused":
		return "Paused"
	case "draining":
		return "Draining"
	case "stopped":
		return "Stopped"
	case "archived":
		return "Archived"
	default:
		return state
	}
}

